// 01 - Industrial defect inspection.
//
// Pipeline: threshold -> external contours -> sort parts into rows ->
//           first part becomes the template -> per-part absdiff ->
//           morphology -> pixel count -> OK / NG.
//
// The demo image is synthetic (generated by tools/make_demo_data) so the
// ground truth is known and the result is reproducible.

#include "portfolio/common.hpp"

#include <numeric>

namespace fs = std::filesystem;
using cv::Mat;
using cv::Point;
using cv::Rect;
using cv::Scalar;
using cv::Size;
using std::vector;

namespace {

struct Options {
    fs::path input;
    fs::path output{"outputs/defect"};
    fs::path templatePath;
    int minArea = 500;
    int minWidth = 20;
    int minHeight = 20;
    double maxHeightRatio = 0.5;
    int openKernel = 3;
    int defectPixels = 40;
    int minBlobArea = 6;
    int invert = -1;  // -1 auto, 0 normal, 1 inverted
    bool gui = false;
    int limit = 0;
};

void usage() {
    std::cout
        << "Usage: defect_inspection --input <image|dir> [options]\n\n"
        << "  --input <path>        Image or directory (required)\n"
        << "  --output <dir>        Output directory (default: outputs/defect)\n"
        << "  --template <path>     Use a fixed template instead of the first part\n"
        << "  --min-area <px>       Minimum contour area (default: 500)\n"
        << "  --defect-pixels <n>   Diff pixels above which a part is NG (default: 40)\n"
        << "  --open-kernel <n>     Morphology kernel for binarisation (default: 3)\n"
        << "  --invert <0|1>        Force threshold polarity (default: auto)\n"
        << "  --limit <n>           Process at most n images\n"
        << "  --gui                 Show annotated images\n"
        << "  --help                Show this help\n\n"
        << "Example:\n"
        << "  ./build/bin/defect_inspection --input assets/defect_parts.png --output outputs/defect\n";
}

Mat toBinary(const Mat& bgr, int openKernel, bool invert) {
    Mat gray;
    cv::cvtColor(bgr, gray, cv::COLOR_BGR2GRAY);
    Mat binary;
    cv::threshold(gray, binary, 0, 255,
                  (invert ? cv::THRESH_BINARY_INV : cv::THRESH_BINARY) | cv::THRESH_OTSU);
    if (openKernel >= 3) {
        const Mat se = cv::getStructuringElement(cv::MORPH_RECT, Size(openKernel, openKernel));
        cv::morphologyEx(binary, binary, cv::MORPH_OPEN, se);
    }
    return binary;
}

vector<Rect> findParts(const Mat& binary, const Options& opt) {
    vector<vector<Point>> contours;
    cv::findContours(binary, contours, cv::RETR_EXTERNAL, cv::CHAIN_APPROX_SIMPLE);

    vector<Rect> boxes;
    const int imageHeight = binary.rows;
    for (const auto& contour : contours) {
        const double area = cv::contourArea(contour);
        const Rect box = cv::boundingRect(contour);
        if (area < opt.minArea) continue;
        if (box.height > imageHeight * opt.maxHeightRatio) continue;
        if (box.width < opt.minWidth || box.height < opt.minHeight) continue;
        boxes.push_back(box);
    }
    return boxes;
}

// Sort boxes into reading order: top-to-bottom rows, then left-to-right.
void sortParts(vector<Rect>& boxes) {
    if (boxes.empty()) return;

    vector<int> heights;
    heights.reserve(boxes.size());
    for (const auto& box : boxes) heights.push_back(box.height);
    std::nth_element(heights.begin(), heights.begin() + heights.size() / 2, heights.end());
    const int medianHeight = heights[heights.size() / 2];
    const int rowTolerance = std::max(8, medianHeight / 2);

    std::sort(boxes.begin(), boxes.end(),
              [](const Rect& a, const Rect& b) { return a.y < b.y; });

    vector<vector<Rect>> rows;
    for (const auto& box : boxes) {
        if (rows.empty() || box.y - rows.back().front().y > rowTolerance) {
            rows.push_back({box});
        } else {
            rows.back().push_back(box);
        }
    }
    for (auto& row : rows) {
        std::sort(row.begin(), row.end(),
                  [](const Rect& a, const Rect& b) { return a.x < b.x; });
    }

    boxes.clear();
    for (const auto& row : rows) {
        boxes.insert(boxes.end(), row.begin(), row.end());
    }
}

struct PartResult {
    int diffPixels = 0;
    int blobs = 0;
    bool ng = false;
};

PartResult inspectPart(const Mat& binary, const Rect& box, const Mat& templ,
                       const Options& opt) {
    PartResult result;
    Mat roi = binary(box).clone();
    cv::resize(roi, roi, templ.size(), 0, 0, cv::INTER_NEAREST);

    Mat diff;
    cv::absdiff(templ, roi, diff);

    // Ignore the resampling border, then remove isolated pixels.
    const int margin = 2;
    if (diff.rows > margin * 2 && diff.cols > margin * 2) {
        diff.rowRange(0, margin).setTo(0);
        diff.rowRange(diff.rows - margin, diff.rows).setTo(0);
        diff.colRange(0, margin).setTo(0);
        diff.colRange(diff.cols - margin, diff.cols).setTo(0);
    }
    const Mat se = cv::getStructuringElement(cv::MORPH_RECT, Size(3, 3));
    cv::morphologyEx(diff, diff, cv::MORPH_OPEN, se);

    result.diffPixels = cv::countNonZero(diff);

    vector<vector<Point>> contours;
    cv::findContours(diff, contours, cv::RETR_EXTERNAL, cv::CHAIN_APPROX_SIMPLE);
    for (const auto& contour : contours) {
        if (cv::contourArea(contour) >= opt.minBlobArea) ++result.blobs;
    }
    result.ng = result.diffPixels > opt.defectPixels;
    return result;
}

int autoPolarity(const Mat& bgr, const Options& opt) {
    if (opt.invert == 0 || opt.invert == 1) return opt.invert;
    Options probe = opt;
    const int normal = static_cast<int>(findParts(toBinary(bgr, opt.openKernel, false), probe).size());
    const int inverted = static_cast<int>(findParts(toBinary(bgr, opt.openKernel, true), probe).size());
    return inverted > normal ? 1 : 0;
}

}  // namespace

int main(int argc, char** argv) {
    const portfolio::Args args(argc, argv);
    if (args.has("help") || args.has("h")) {
        usage();
        return 0;
    }

    Options opt;
    opt.input = args.get("input");
    opt.output = args.get("output", "outputs/defect");
    opt.templatePath = args.get("template");
    opt.minArea = args.getInt("min-area", opt.minArea);
    opt.minWidth = args.getInt("min-width", opt.minWidth);
    opt.minHeight = args.getInt("min-height", opt.minHeight);
    opt.maxHeightRatio = args.getDouble("max-height-ratio", opt.maxHeightRatio);
    opt.openKernel = args.getInt("open-kernel", opt.openKernel);
    opt.defectPixels = args.getInt("defect-pixels", opt.defectPixels);
    opt.minBlobArea = args.getInt("min-blob-area", opt.minBlobArea);
    opt.invert = args.getInt("invert", opt.invert);
    opt.gui = args.has("gui");
    opt.limit = args.getInt("limit", opt.limit);

    if (opt.input.empty()) {
        usage();
        return 1;
    }

    auto images = portfolio::collectImages(opt.input);
    if (images.empty()) {
        std::cerr << "No images found at: " << opt.input << '\n';
        return 1;
    }
    if (!portfolio::ensureDirectory(opt.output)) return 1;

    struct Job {
        fs::path path;
        Mat bgr;
        Mat binary;
        vector<Rect> boxes;
    };

    vector<Job> jobs;
    int skipped = 0;
    for (const auto& path : images) {
        Mat bgr = cv::imread(path.string(), cv::IMREAD_COLOR);
        if (bgr.empty()) {
            std::cerr << "Cannot read image: " << path << '\n';
            ++skipped;
            continue;
        }
        Job job;
        job.path = path;
        job.bgr = bgr;
        const int invert = autoPolarity(bgr, opt);
        job.binary = toBinary(bgr, opt.openKernel, invert != 0);
        job.boxes = findParts(job.binary, opt);
        sortParts(job.boxes);
        jobs.push_back(std::move(job));
        if (opt.limit > 0 && static_cast<int>(jobs.size()) >= opt.limit) break;
    }

    if (jobs.empty()) {
        std::cerr << "No readable images.\n";
        return 1;
    }

    Mat templ;
    if (!opt.templatePath.empty()) {
        const Mat templateImage = cv::imread(opt.templatePath.string(), cv::IMREAD_COLOR);
        if (templateImage.empty()) {
            std::cerr << "Cannot read template: " << opt.templatePath << '\n';
            return 1;
        }
        templ = toBinary(templateImage, opt.openKernel, autoPolarity(templateImage, opt) != 0);
    } else {
        for (const auto& job : jobs) {
            if (!job.boxes.empty()) {
                templ = job.binary(job.boxes.front()).clone();
                break;
            }
        }
    }

    if (templ.empty()) {
        std::cerr << "No template could be built (no parts found). Try --min-area / --invert.\n";
        return 1;
    }

    std::cout << "Template size: " << templ.cols << " x " << templ.rows << '\n';

    const fs::path csvPath = opt.output / "parts.csv";
    std::ofstream csv(csvPath);
    csv << "image,part,x,y,width,height,diff_pixels,blobs,verdict,elapsed_ms\n";

    int totalParts = 0;
    int totalNg = 0;
    int imagesWithoutParts = 0;
    double totalMs = 0.0;

    for (const auto& job : jobs) {
        portfolio::Stopwatch watch;
        Mat annotated = job.bgr.clone();
        int imageNg = 0;

        if (job.boxes.empty()) {
            ++imagesWithoutParts;
            cv::putText(annotated, "NO PART DETECTED", Point(24, 44),
                        cv::FONT_HERSHEY_SIMPLEX, 1.0, Scalar(0, 0, 255), 3, cv::LINE_AA);
            csv << job.path.filename().string() << ",0,0,0,0,0,0,0,NO_PART,0\n";
        }

        vector<PartResult> results;
        results.reserve(job.boxes.size());
        for (size_t i = 0; i < job.boxes.size(); ++i) {
            const Rect& box = job.boxes[i];
            const PartResult result = inspectPart(job.binary, box, templ, opt);
            results.push_back(result);
            ++totalParts;
            if (result.ng) {
                ++totalNg;
                ++imageNg;
            }

            const Scalar color = result.ng ? portfolio::ngColor() : portfolio::okColor();
            cv::rectangle(annotated, box, color, 2);
            const std::string text = std::string(result.ng ? "NG" : "OK") + " #" +
                                     std::to_string(i + 1) + "  " +
                                     std::to_string(result.diffPixels) + " px";
            portfolio::drawBadge(annotated, box, color, text, 0.5);
        }

        const double elapsed = watch.ms();
        totalMs += elapsed;

        const std::string summary = "parts=" + std::to_string(job.boxes.size()) +
                                    "  ng=" + std::to_string(imageNg);
        const Point summaryOrigin(24, annotated.rows - 22);
        cv::putText(annotated, summary, summaryOrigin, cv::FONT_HERSHEY_SIMPLEX, 0.9,
                    Scalar(0, 0, 0), 5, cv::LINE_AA);
        cv::putText(annotated, summary, summaryOrigin, cv::FONT_HERSHEY_SIMPLEX, 0.9,
                    Scalar(255, 255, 255), 2, cv::LINE_AA);

        const fs::path annotatedPath = opt.output / (job.path.stem().string() + "_annotated.jpg");
        cv::imwrite(annotatedPath.string(), annotated);

        for (size_t i = 0; i < job.boxes.size(); ++i) {
            const Rect& box = job.boxes[i];
            const PartResult& result = results[i];
            csv << job.path.filename().string() << ',' << (i + 1) << ',' << box.x << ','
                << box.y << ',' << box.width << ',' << box.height << ','
                << result.diffPixels << ',' << result.blobs << ','
                << (result.ng ? "NG" : "OK") << ',' << portfolio::fixed(elapsed, 2) << '\n';
        }

        std::cout << job.path.filename().string() << ": " << job.boxes.size() << " parts, "
                  << imageNg << " NG, " << portfolio::fixed(elapsed, 1) << " ms\n";

        if (opt.gui) {
            cv::imshow("defect inspection", annotated);
            cv::waitKey(1);
        }
    }

    csv.close();

    std::cout << "\n===== Defect inspection summary =====\n"
              << "Images        : " << jobs.size() << " (skipped " << skipped << ")\n"
              << "Parts         : " << totalParts << '\n'
              << "NG parts      : " << totalNg << " ("
              << portfolio::fixed(totalParts ? 100.0 * totalNg / totalParts : 0.0, 1) << "%)\n"
              << "Images w/o part: " << imagesWithoutParts << '\n'
              << "Avg time      : " << portfolio::fixed(totalMs / jobs.size(), 2)
              << " ms/image\n"
              << "Report        : " << csvPath << '\n';

    if (opt.gui) {
        std::cout << "Press any key in the image window to exit.\n";
        cv::waitKey(0);
    }
    return 0;
}
